def estimate_nightly_throughput(series_count=50_000_000, window_hours=4):
    series_per_sec = series_count / (window_hours * 3600)
    return round(series_per_sec, 1)  # ~3,472 series/sec sustained

def build_daily_feature_row(pos_sales, erp_on_hand, promo_flag, lead_days):
    is_oos = (erp_on_hand <= 0)
    return {
        'sales': uncensor_if_oos(pos_sales, is_oos),
        'promo': int(promo_flag),
        'lead_days': max(1, lead_days)
    }

def infer_tft_partition(parquet_batch, model_weights):
    # Batch size 4096 series per GPU forward pass
    preds = model_weights.predict_quantiles(parquet_batch, quantiles=[0.1, 0.5, 0.9])
    return enforce_quantile_monotonicity(preds)

def solve_category_mint(base_preds_vec, summing_matrix_s, w_diag):
    # Diagonal WLS MinT scales linearly O(N) for huge retail trees
    w_inv = 1.0 / np.maximum(w_diag, 1e-6)
    st_winv = summing_matrix_s.T * w_inv
    return summing_matrix_s @ np.linalg.solve(st_winv @ summing_matrix_s, st_winv @ base_preds_vec)

def round_to_moq_and_pack(net_req, moq, case_pack):
    if net_req <= 0:
        return 0
    qty = max(net_req, moq)
    return math.ceil(qty / case_pack) * case_pack

def check_intraday_burn(hourly_sales, remaining_stock, hours_to_next_delivery):
    projected_burn = hourly_sales * hours_to_next_delivery
    if projected_burn > remaining_stock * 0.9:
        return 'EMERGENCY_TRANSFER_ALERT'
    return 'NORMAL'

def compute_fva(actuals, ml_preds, planner_preds):
    ml_wape = sum(abs(a - m) for a, m in zip(actuals, ml_preds)) / max(sum(actuals), 1.0)
    pl_wape = sum(abs(a - p) for a, p in zip(actuals, planner_preds)) / max(sum(actuals), 1.0)
    return {'fva_gain_pct': round((ml_wape - pl_wape) * 100, 2)}
